  const chunk=missing.slice(i,i+100);let rows=[];
  if(typeof bucket.createSignedUrls==='function'){const {data,error}=await bucket.createSignedUrls(chunk,3600);if(!error)rows=data||[]}
  else rows=await Promise.all(chunk.map(async path=>{const {data,error}=await bucket.createSignedUrl(path,3600);return {path,signedUrl:error?'':data?.signedUrl}}));
  if(cloudUser?.id!==owner||cloudSessionEpoch!==epoch)return new Map();
