function cloudRecoveryView(){app.innerHTML=`<section class="card cloud-auth-card"><h1>There’s unfinished saving on this device.</h1><p>A recovery copy was kept for this account. Your cloud records have been retrieved.</p><p>${cloudRecoveryCopy.version===cloudVersion?'The cloud version still matches. You can restore and sync this device’s progress.':'Another device has saved a newer version. Keep the cloud version to avoid overwriting it. Download your recovery copy first if needed.'}</p><div class="review-actions"><button class="btn quiet" data-cloud="closeRecovery">Continue using the app</button><button class="btn" data-cloud="recoverDraft" ${cloudRecoveryCopy.version===cloudVersion?'':'disabled'}>Restore this device’s progress</button><button class="btn quiet" data-cloud="keepCloud">Use cloud version</button><button class="text-button" data-cloud="downloadDraft">Download recovery copy</button></div></section>`}
