profileLinks=function(){if(!cloudEnabled)return cloudProfileLinksBefore();return cloudProfileLinksBefore()+`<section class="card"><button class="profile-action" data-nav="access"><span>Account & sync</span><small>Open →</small></button>${cloudRole?'<button class="profile-action" data-cloud="moderation"><span>Moderator queue</span><small>Open →</small></button>':''}</section>`};
accessUI=function(){if(!cloudEnabled){cloudAccessBefore();return}app.innerHTML=`<button class="back" data-nav="settings">← Settings & support</button><header class="ui-page-head"><div class="eyebrow">YOUR ACCOUNT</div><h1>Your learning account.</h1><p>${esc(cloudUser.email)}</p></header><section class="card"><h2>Cloud progress</h2><p id="cloudSyncState">${cloudPending?'Changes are waiting to sync.':'Your last save is synced.'}</p><p class="hint">Questions, answers, and profile details are stored in your account. Review progress, saved reads, and preferences are private. Unsynced progress has a recovery copy on this device.</p><div class="review-actions"><button class="btn" data-cloud="retrySync">Retry saving</button><button class="btn quiet" data-cloud="refresh">Refresh account</button></div></section><section class="card"><h2>Account controls</h2><button class="text-button" data-cloud="sendReset">Send a password reset email</button><p><button class="btn quiet" data-cloud="logout">Sign out</button></p><div id="logoutChoice"></div></section>`};
privacyView=function(){if(!cloudEnabled){cloudPrivacyBefore();return}app.innerHTML=`<button class="back" data-nav="settings">← Settings</button><article class="card privacy-copy"><div class="eyebrow">PRIVACY NOTICE</div><h1>Your information, explained.</h1><p>Toolbox is operated by JV Ursal. Privacy contact: ${esc(hubConfig.privacyContact||'Not configured; registration is closed.')}</p><h2>What is shared</h2><p>Your name, self-reported rank, department, bio, experience, country, and profile photo can be read by signed-in members. Posted questions, answers, photos, reactions, and outcomes are shared with signed-in members. Do not post confidential vessel, company, location, or personal information.</p><h2>What stays private</h2><p>Your email and authentication records are managed by Supabase Auth. Saved discussions, review attempts, practice scores, preferences, and your last view are stored under your account with access controls. Reports and feedback are readable by authorized moderators.</p><h2>Storage and providers</h2><p>Cloudflare serves the website and may process security/access logs. Supabase processes account, database, and photo storage. Their policies and the project’s configured hosting regions apply. The browser retains a sign-in session and account-specific recovery copies of unsynced profile details, profile photos, and personal progress. It is not a secure document vault.</p><h2>Retention and your choices</h2><p>Account records remain while the account is active unless removed during moderation or through a deletion request. Contact the operator to request access, corrections, or deletion. Shared discussions may need anonymization to preserve context. Provider backups and logs may remain for their configured retention periods; ask the operator for those details. Signing out does not delete shared posts. Clearing browser data removes device recovery copies, not cloud records.</p><h2>Optional features</h2><p>Review scores are for personal practice, not certification. Facebook opens separately and receives no automatic transfer of your local profile. No advertising tracker or push notifications are implemented.</p><p class="hint">This notice describes the implemented design. Before public registration, the operator must verify actual regions, retention settings, privacy contact, and request handling against the configured services.</p></article>`};
function cloudTerms(){app.innerHTML=`<article class="card privacy-copy"><button class="back" data-cloud="signin">← Sign in</button><h1>Participate with care.</h1><p>This free Toolbox helps seafarers exchange experience and review questions. It does not replace vessel procedures, official training, manuals, responsible officers, or emergency support.</p><p>Post only content you have permission to share. No confidential documents, personal attacks, spam, or unsafe instructions. Clearly distinguish observations, firsthand experience, and suggestions. Moderators may hide content and review reports.</p><p>Rank and experience are self-reported. Popular answers, badges, and practice scores do not establish technical competence or correctness. Review keys follow the supplied source copies and may contain mistakes.</p><p>You remain responsible for the information you post. You allow the Toolbox to display it to signed-in members as part of the relevant discussion. Contact ${esc(hubConfig.privacyContact||'the operator')} about your content or account.</p></article>`}
feedbackView=function(){cloudFeedbackBefore();if(!cloudEnabled)return;const f=app.querySelector('#profileFeedbackForm');if(f){const hint=f.querySelector('p.hint');if(hint)hint.textContent='Sent to the app’s moderator queue. Do not include confidential information.';const b=f.querySelector('button');if(b)b.textContent='Send feedback'}};
async function cloudModeration(){if(!cloudRole)return;cloudLoading('Retrieving reports…');try{const reports=await cloudRows('hub_reports'),feedback=await cloudRows('hub_feedback');document.body.classList.remove('cloud-auth');app.innerHTML=`<button class="back" data-nav="profile">← Profile</button><h1>Moderator queue</h1><p class="hint">Visibility changes require a reason and are recorded on the server.</p>${reports.map(r=>`<section class="card"><h2>Reported discussion</h2><p>${esc(r.reason)}</p><p class="hint">${esc(r.created_at)}</p><button class="text-button" data-open="${r.question_id}">Open discussion →</button><form class="cloudModerateForm"><input name="target" type="hidden" value="${r.question_id}"><label class="field">Reason<textarea required name="reason" minlength="3"></textarea></label><button class="btn" name="hide" value="true">Hide question</button><button class="btn quiet" name="hide" value="false">Restore question</button></form></section>`).join('')||'<p>No reports yet.</p>'}<h2>App feedback</h2>${feedback.map(f=>`<article class="card"><strong>${esc(f.topic)}</strong><p>${esc(f.message)}</p></article>`).join('')||'<p>No feedback yet.</p>'}`;for(const f of app.querySelectorAll('.cloudModerateForm'))f.onsubmit=async e=>{e.preventDefault();await cloudAction(e.submitter,'Saving…',async()=>{const{error}=await hubClient.rpc('hub_moderate',{kind:'question',target:f.elements.target.value,hide:e.submitter.value==='true',reason:f.elements.reason.value});if(error)throw error;await loadCloudFeed();toast('Visibility updated.');})}}catch(e){cloudError=e.message;render()}}
function cloudTourCard(){if(state.hubTourCompleted||page!=='home')return;app.insertAdjacentHTML('afterbegin',`<section class="card cloud-start"><div class="eyebrow">YOUR FIRST STEPS</div><h2>Start with what you need today.</h2><p>Use <strong>Ask</strong> to describe a problem, or <strong>Answer</strong> to choose topics you can help with. Open <strong>Library</strong> to find an existing discussion. The navigation stays at the bottom on your phone.</p><div class="review-actions"><button class="btn quiet" data-nav="help">Show me around →</button><button class="text-button" data-cloud="dismissTour">Got it—I'm ready</button></div></section>`)}
function cloudReturnCard(){if(!cloudReturning||cloudWelcomeDismissed||!state.hubOnboardingCompleted||!['home','learn','progress','review'].includes(page))return;app.insertAdjacentHTML('afterbegin',`<aside class="cloud-return card"><div><span class="eyebrow">WELCOME BACK, ${esc(qProfileName().split(' ')[0])}</span><h2>Good to have you aboard again.</h2><p>${!cloudEnabled?'Your saved progress on this device is ready.':state.review.session&&!state.review.session.done?'Your unfinished review round is ready when you are.':`${all().filter(q=>!q.answers.length).length} questions are waiting for shared experience. One useful contribution is enough to start.`}</p><button class="text-button" data-nav="${state.review.session&&!state.review.session.done?'review':'home'}">${state.review.session&&!state.review.session.done?'Continue reviewing':'Find a question to answer'} →</button></div><button class="cloud-dismiss" data-cloud="dismissWelcome" aria-label="Dismiss welcome-back message">×</button></aside>`)}
render=function(){if(!cloudEnabled){cloudRenderBefore();if(state.hubOnboardingCompleted){cloudReturnCard();cloudTourCard()}return}if(!cloudUser||cloudRecovery){cloudAuthView();return}if(!cloudReady){if(cloudError){document.body.classList.add('cloud-auth');app.innerHTML=`<section class="card cloud-auth-card"><h1>We couldn’t retrieve your workspace.</h1><p>${esc(cloudError)}</p><p>Your cloud records have not been replaced.</p><button class="btn" data-cloud="restore">Retry retrieving</button><button class="text-button" data-cloud="forceLogout">Sign out</button></section>`}else cloudLoading('Retrieving your workspace…');return}if(cloudRecoveryCopy&&cloudReviewRecovery){cloudRecoveryView();return}document.body.classList.remove('cloud-auth');cloudRenderBefore();cloudCleanCopy();cloudReturnCard();cloudTourCard();cloudSyncNotice()};
persist=function(){if(!cloudEnabled)return cloudPersistBefore();if(!cloudReady)return false;awardQABadges();return cacheCloudWorkspace()};
saveLastView=function(){if(!cloudEnabled)return cloudSaveViewBefore();if(!cloudReady||!state.hubOnboardingCompleted)return false;const v={page,selected:page==='detail'?selected:null,shelfTopic,shelfFileQuery,shelfTopicQuery,shelfStatus,shelfReturn,qaView,qaDepartment,query,topic,sort,scrollY:window.scrollY||0};if(JSON.stringify(v)!==JSON.stringify(state.lastView)){state.lastView=v;cloudSaveDeviceView()}return true};
nav=function(p){if(cloudEnabled&&(!cloudUser||!cloudReady||cloudRecovery)){render();return}cloudNavBefore(p);if(cloudEnabled&&cloudReady)showCloudSync(cloudPending?'Saving your progress…':'Your place is saved.',cloudPending)};
// Capture writes before legacy local handlers; no cloud write trusts a display name.
document.addEventListener('submit',e=>{if(!cloudEnabled||!cloudReady||!cloudUser)return;const f=e.target;if(!['askForm','answerForm','qaProfileForm','outcomeForm','qaReportForm','profileFeedbackForm'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();cloudAction(e.submitter||f.querySelector('button[type=submit],button.btn'),'Saving…',async()=>{if(f.id==='askForm'||f.id==='answerForm')return cloudPost(f,f.id==='askForm'?'question':'answer');if(f.id==='qaProfileForm')return saveCloudProfile(f);const d=Object.fromEntries(new FormData(f));if(f.id==='outcomeForm'){const{error}=await hubClient.from('hub_questions').update({status:'Resolved',outcome:d.outcome.trim()}).eq('id',selected).select('id').single();if(error)throw error;await loadCloudFeed();render()}else if(f.id==='qaReportForm'){await cloudInsertOnce('hub_reports',{id:formRequestId(f),question_id:selected,reason:d.reason.trim()});f.innerHTML='<p role="status">Report sent for moderator review. Thank you.</p>'}else{await cloudInsertOnce('hub_feedback',{id:formRequestId(f),message:d.message.trim(),topic:d.topic});f.innerHTML='<p role="status">Feedback sent. Thank you for helping improve the Toolbox.</p>'}})},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(!cloudEnabled){if(d.cloud==='dismissTour'||d.cloud==='dismissWelcome'){e.preventDefault();e.stopImmediatePropagation();if(d.cloud==='dismissTour'){state.hubTourCompleted=true;persist()}else cloudWelcomeDismissed=true;render()}return;}if(d.cloud){e.preventDefault();e.stopImmediatePropagation();cloudHandle(d.cloud,b);return}if(!cloudReady)return;if(d.vote||d.questionUp||d.accept||d.profileSupport){e.preventDefault();e.stopImmediatePropagation();cloudAction(b,'Saving…',async()=>{if(d.profileSupport){const c=cloudBoard?.candidates.find(c=>c.id===d.profileSupport);if(!c)throw Error('This profile is not in the current shortlist.');const r=c.supported?await hubClient.from('hub_support').delete().eq('week',cloudBoard.week).eq('candidate',c.id).eq('voter',cloudUser.id):await hubClient.from('hub_support').insert({week:cloudBoard.week,candidate:c.id});if(r.error)throw r.error;cloudBoard=null;await fetchCloudBoard();render();return}if(d.accept){const{error}=await hubClient.from('hub_questions').update({accepted:d.accept}).eq('id',selected).select('id').single();if(error)throw error}else{const answer=!!d.vote,id=d.vote||d.questionUp,table=answer?'hub_answer_votes':'hub_question_votes',field=answer?'answer_id':'question_id',already=(answer?state.votes:state.questionUps).includes(id);const result=already?await hubClient.from(table).delete().eq(field,id).eq('user_id',cloudUser.id):await hubClient.from(table).insert({[field]:id});if(result.error)throw result.error}await loadCloudFeed();render()});}},true);
async function cloudHandle(action,b){if(action==='logout'||action==='forceLogout'){await cloudSignOutNow();return}if(action==='reviewRecovery'){cloudReviewRecovery=true;render();return}if(action==='closeRecovery'){cloudReviewRecovery=false;render();return}if(action==='dismissTour'){state.hubTourCompleted=true;persist();render();return}if(['signin','signup','reset'].includes(action)){cloudAuthMode=action;cloudRecovery=false;render();return}if(action==='privacy'){privacyView();app.insertAdjacentHTML('afterbegin','<button class="back" data-cloud="signin">← Sign in</button>');return}if(action==='terms'){cloudTerms();return}if(action==='dismissWelcome'){cloudWelcomeDismissed=true;render();return}if(action==='recoverDraft'){cloudMergeBackup(cloudRecoveryCopy);cloudRecoveryCopy=null;cloudReviewRecovery=false;cloudConflict=false;finishCloudRestore();cacheCloudWorkspace();void flushCloudWorkspace();return}if(action==='keepCloud'){localStorage.removeItem(cloudCacheKey());cloudRecoveryCopy=null;cloudProfileDraft=null;cloudPending=false;cloudConflict=false;cloudReviewRecovery=false;await restoreCloud(cloudUser);return}if(action==='downloadDraft'){const url=URL.createObjectURL(new Blob([JSON.stringify(cloudRecoveryCopy,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='hub-progress-recovery.json';a.click();URL.revokeObjectURL(url);return}if(action==='restore'){await restoreCloud(cloudUser);return}if(action==='moderation'){await cloudModeration();return}await cloudAction(b,action==='refresh'?'Retrieving account…':'Saving…',async()=>{if(action==='retrySync'){if(cloudConflict)throw Error('Reload before reconciling a newer cloud version. Your device recovery copy is kept.');if(!await flushCloudWorkspace())throw Error('Still not synced. Your recovery copy is on this device.');return}if(action==='refresh'){await loadCloudFeed();render();showCloudSync('Account refreshed.');return}if(action==='sendReset'){const{error}=await hubClient.auth.resetPasswordForEmail(cloudUser.email,{redirectTo:location.origin+'/?recovery=1'});if(error)throw error;toast('Check your email for a reset link.');return}})}
let cloudBoard=null,cloudBoardLoading=false,cloudBoardError='';
async function fetchCloudBoard(){if(cloudBoardLoading)return;cloudBoardLoading=true;cloudBoardError='';try{const{data,error}=await hubClient.rpc('hub_get_leaderboard');if(error)throw error;cloudBoard=data}catch(e){cloudBoardError=e.message}finally{cloudBoardLoading=false}}
leaderboardView=function(){if(!cloudEnabled){cloudLeaderboardBefore();return}if(!cloudBoard){app.innerHTML='<button class="back" data-nav="progress">← Progress</button><h1>Top seafarers</h1><p role="status">'+(cloudBoardError?esc(cloudBoardError):'Retrieving this week’s contributors…')+'</p>';if(!cloudBoardLoading&&!cloudBoardError)fetchCloudBoard().then(()=>{if(page==='leaderboard')render()});return}app.innerHTML=`<button class="back" data-nav="progress">← Progress</button><header class="ui-page-head"><div class="eyebrow">CONTRIBUTIONS EARN THE SPOT</div><h1>Top seafarers</h1><p>Weekly shortlist · ${esc(cloudBoard.week)} · Monday cutoff, UTC</p></header><details class="review-notes"><summary>How this week’s ranking works</summary><p>Points earned before Monday qualify up to ten contributors. A question upvote earns 1 point, a Helpful answer vote earns 2, and asker acceptance earns 5 for another person’s answer. Posting alone and self-votes earn no points.</p><p>The shortlist stays fixed for the week. Member support votes rank those eligible profiles; ties use qualifying points, then a stable account ID. Support can be removed. The next week gets a new shortlist and fresh support votes.</p><p>Recognition is for participation, not technical qualifications or verified advice.</p></details>${cloudBoard.candidates.map((c,i)=>`<article class="card cloud-rank-row"><span class="rank-pos">${i+1}</span><div class="rank-person"><h2>${esc(c.name)}</h2><p>${esc(c.rank)} · ${esc(c.department)}</p><span class="tag">${c.points} qualifying points</span></div><button class="btn quiet" data-profile-support="${c.id}" aria-pressed="${c.supported}" ${c.id===cloudUser.id?'disabled':''}>${c.supported?'✓ Supported':'↑ Support'} · ${c.votes}</button></article>`).join('')||'<section class="card"><h2>The first shortlist is ahead of us.</h2><p>Contribute useful questions and answers this week. Points from other members qualify contributors for the next Monday’s shortlist.</p><button class="btn" data-nav="home">Find a question →</button></section>'}`};
if(cloudEnabled){
 all=()=>cloudQuestions;own=q=>!!cloudUser&&q.owner===cloudUser.id;ownAnswer=a=>!!cloudUser&&a.owner===cloudUser.id;
 hubClient=window.supabase.createClient(hubConfig.supabaseUrl,hubConfig.publishableKey,{global:{fetch:hubTimedFetch},auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storageKey:'hub-auth-v1'}});
 hubClient.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){cloudRecovery=true;cloudUser=session?.user||null;render()}if(event==='SIGNED_OUT'){cloudRecovery=false;cloudUser=null;cloudReady=false;state=blankHubState();cloudQuestions=[];render()}if(event==='SIGNED_IN'&&session?.user&&!cloudReady&&!cloudRecovery&&!cloudSigningOut)setTimeout(()=>restoreCloud(session.user),0)});
 (async()=>{cloudLoading('Finding your place…');const sessionResult=await hubClient.auth.getSession();const{data,error}=await hubClient.auth.getUser();if(error&&sessionResult.data?.session&&!cloudRecovery){cloudUser=sessionResult.data.session.user;cloudError='Your connection could not be verified. Reconnect and retry retrieving your workspace.';render();return}if(data.user&&!cloudRecovery&&!cloudReady)await restoreCloud(data.user);else render()})();
 window.addEventListener('online',()=>{if(cloudPending&&!cloudConflict)cloudScheduleSave()});window.addEventListener('pagehide',()=>{if(cloudPending)cloudWriteBackup();cloudSaveDeviceView()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){if(cloudPending)cloudWriteBackup();cloudSaveDeviceView()}else if(cloudPending)cloudScheduleSave()});
}else render();
